mapper.select:
SELECT 
  FROM oa_iam.permission_delegation
 WHERE tenant_id = #{tenantId} AND id = #{id}

SELECT 
  FROM oa_iam.permission_delegation
 WHERE tenant_id = #{tenantId}
   AND (delegator_identity_id = CAST(#{identityId} AS uuid)
        OR delegatee_identity_id = CAST(#{identityId} AS uuid))

   AND id > #{cursor}

 ORDER BY id
 LIMIT #{limit}

SELECT 
  FROM oa_iam.permission_delegation
 WHERE tenant_id = #{tenantId}
   AND delegatee_identity_id = CAST(#{delegateeIdentityId} AS uuid)
   AND status = 'ACTIVE'
   AND valid_from <= #{now}
   AND valid_to > #{now}
 ORDER BY id

SELECT 
  FROM oa_iam.permission_delegation
 WHERE tenant_id = #{tenantId}
   AND status = 'ACTIVE'
   AND valid_from <= #{now}
   AND valid_to > #{now}
   AND perm_codes @> jsonb_build_array(#{permCode})
 ORDER BY id
